export default function nextFeed({ feeds, previousState }) {
  if (!Array.isArray(feeds) || !feeds.every((x) => typeof x === "string" && /^https?:\/\//.test(x)))
    throw Error("Configure feed URLs");
  const i = previousState?.index ?? 0;
  if (i === feeds.length)
    return { state: { index: i }, more: false, url: "https://example.invalid" };
  return { state: { index: i + 1 }, more: true, url: feeds[i] };
}

