export default async function nextItem(
  { items, feed, previousState, acknowledgeKey, m365Chat, securityChat, itChat },
  context,
) {
  if (!Array.isArray(items)) throw Error("Expected feed items");
  let saved = (await context.state.get("rss-route-progress")) ?? { seen: [], pending: null };
  if (saved.pending) {
    if (acknowledgeKey !== saved.pending)
      throw Error("Pending article; check destination before acknowledging: " + saved.pending);
    saved.seen.push(saved.pending);
    saved.pending = null;
    await context.state.set("rss-route-progress", saved);
  }
  const i = previousState?.feed === feed ? previousState.index : 0;
  if (i === items.length)
    return {
      state: { feed, index: i },
      more: false,
      process: false,
      key: "",
      text: "unused",
      route: "IT",
      chatId: itChat,
    };
  const e = items[i],
    key = feed + "\n" + e.link,
    state = { feed, index: i + 1 };
  if (saved.seen.includes(key))
    return { state, more: true, process: false, key, text: "unused", route: "IT", chatId: itChat };
  const route = e.link.includes("techcommunity.microsoft.com")
    ? "M365"
    : /資安|資訊安全|安全|外洩|監控|威脅|漏洞|封鎖|修補|攻擊|入侵|個資|隱私|私密|騙|社交工程|釣魚|駭|Security|security|Secure|secure/.test(
          e.title,
        )
      ? "Security"
      : "IT";
  const text = e.title + "\n" + e.link;
  if (text.length > 4096) throw Error("Telegram message exceeds limit");
  return {
    state,
    more: true,
    process: true,
    key,
    text,
    route,
    chatId: route === "M365" ? m365Chat : route === "Security" ? securityChat : itChat,
  };
}

