export default async function rssPending({ key }, context) {
  const s = (await context.state.get("rss-route-progress")) ?? { seen: [], pending: null };
  if (s.pending) throw Error("Resolve pending article first");
  s.pending = key;
  await context.state.set("rss-route-progress", s);
  return { key };
}

