export default async function rssDone({ key }, context) {
  const s = await context.state.get("rss-route-progress");
  if (s?.pending !== key) throw Error("Pending article mismatch");
  s.seen.push(key);
  s.pending = null;
  await context.state.set("rss-route-progress", s);
  return { done: true };
}
